    const inner = record.modelInner || record.model
    const host = element?.closest?.('[data-nimbus-tech]')
    const track = Array.from(element?.ownerDocument?.querySelectorAll?.('[id="nimbus-tech-scroll"]') || [])
        .find((node: any) => node.getBoundingClientRect().width > 1 && node.getBoundingClientRect().height > 1) as HTMLElement
        || host?.closest?.('[data-framer-name="Nimbus — Hero and Tech specs"]')
