        // Give the GLB contour lines their own material; its shared placeholder alpha is only 0.08.
        inner.traverse((node: any) => {
            if (!node.isLine || node.userData._nimbusContourMaterial) return
            const original = Array.isArray(node.material) ? node.material[0] : node.material
            const material = original.clone()
            material.color.set("#e97835")
            material.transparent = true
            material.opacity = 0.28
            material.depthWrite = false
            material.toneMapped = false
            material.needsUpdate = true
            node.material = material
            node.userData._nimbusContourMaterial = true
        })
        record.model.updateWorldMatrix(true, true)
        const box = new THREE.Box3().setFromObject(inner)
        const size = box.getSize(new THREE.Vector3())
