        const fit = state.fit || (state.fit = { box: new THREE.Box3(), center: new THREE.Vector3(), cameraPoint: new THREE.Vector3(), shift: new THREE.Vector3(), right: new THREE.Vector3(), up: new THREE.Vector3(), localA: new THREE.Vector3(), localB: new THREE.Vector3(), corners: Array.from({ length: 8 }, () => new THREE.Vector3()) })
        fit.box.setFromObject(record.model)
